// 识别并清理客户端自动注入的内容，让「用户亲手写的话」和「系统塞进去的上下文」分开。

const CLAUDE_CONTEXT_PREFIXES = [
  '<command-name>',
  '<command-message>',
  '<local-command-',
  '<system-reminder>',
  'This session is being continued from a previous conversation',
  'Caveat: The messages below were generated by the user',
  '[Request interrupted by user',
  // 后台任务结束时客户端自动发来的通知，不是用户写的
  '<task-notification>',
  // 工作流（workflow）里的子 agent 收到的任务说明，由程序生成
  '[Workflow harness',
];

const CODEX_CONTEXT_PREFIXES = [
  '<environment_context>',
  '# AGENTS.md instructions',
  '<user_instructions>',
  '<in-app-browser-context',
  '<permissions instructions>',
];

function startsWithAny(text: string, prefixes: string[]): boolean {
  const t = text.trimStart();
  return prefixes.some((p) => t.startsWith(p));
}

export function isClaudeContext(text: string): boolean {
  return startsWithAny(text, CLAUDE_CONTEXT_PREFIXES);
}

export function isCodexContext(text: string): boolean {
  return startsWithAny(text, CODEX_CONTEXT_PREFIXES);
}

/** 去掉图片占位标签，例如 `<image name=[Image #1] path="..."></image>` */
export function stripImageTags(text: string): string {
  return text
    .replace(/<image\b[^>]*>/g, '')
    .replace(/<\/image>/g, '')
    .trim();
}

/** Codex 在用户附带文件时，会把文件清单拼在前面，真正的请求放在 `## My request:` 之后 */
export function extractCodexRequest(text: string): string {
  const m = text.match(/\n## My request(?: for Codex)?:\n([\s\S]*)$/);
  return m ? m[1] : text;
}

/** 把工具的输入/输出（字符串、对象或内容块数组）统一成文本 */
export function toText(value: unknown): string {
  if (value == null) return '';
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) {
    return value
      .map((item) => (item && typeof item === 'object' && 'text' in item ? String(item.text) : ''))
      .filter(Boolean)
      .join('\n');
  }
  return JSON.stringify(value);
}

/** 没有标题的会话，用用户第一条消息截断后作为标题 */
export function titleFrom(text: string, max = 40): string {
  const one = text.replace(/\s+/g, ' ').trim();
  return one.length > max ? one.slice(0, max) + '…' : one;
}
